var PL3 = window.PL3 || {};
PL3.TITLE = PL3.TITLE || {};
PL3.AVDEF = PL3.AVDEF || {};
PL3.AVDIR = PL3.AVDIR || '';
PL3.avUrl = PL3.avUrl || function(name,url){
  var u=String(url||'').trim();
  if(/^https?:\/\//i.test(u)||/^data:image\//i.test(u)) return u;
  var k=PL3.AVDEF[String(name||'')]; return k ? PL3.AVDIR+k+'.png' : '';
};
PL3.av = PL3.av || function(name,size,opts){
  opts=opts||{}; var s=Math.max(20,Number(size)||36),u=PL3.avUrl(name,opts.url),txt=String(name||'؟').trim();
  var ini=(txt.split(/\s+/).filter(Boolean).slice(0,2).map(function(x){return x[0]}).join('')||'؟');
  var r=opts.r||Math.round(s*.28)+'px';
  return u?'<img src="'+u.replace(/"/g,'&quot;')+'" alt="" style="width:'+s+'px;height:'+s+'px;border-radius:'+r+';object-fit:cover;flex:none">':'<span aria-hidden="true" style="width:'+s+'px;height:'+s+'px;border-radius:'+r+';display:grid;place-items:center;background:#e7ecf1;color:#243244;font:900 '+Math.round(s*.38)+'px Cairo;flex:none">'+ini+'</span>';
};
