O.errorText=function(e){var code=String(e&&((e.code||'')+' '+(e.message||''))||e||'');var map=[['target_profile_not_found','لم يوجد حساب بهذا المعرّف'],['manage_members_denied','لا توجد صلاحية لإدارة الأعضاء'],['manage_finance_required','لا توجد صلاحية مالية'],['manage_integrations_required','لا توجد صلاحية لإدارة التكاملات'],['fee_plan_not_active','الباقة غير نشطة'],['active_membership_required','العضوية غير نشطة'],['subscription_not_billable','الاشتراك غير قابل للفوترة'],['payment_exceeds_outstanding','المبلغ يتجاوز المتبقي'],['invoice_not_payable','الفاتورة غير قابلة للدفع'],['secrets_not_allowed','لا تضع كلمات مرور أو مفاتيح سرية هنا'],['duplicate key','هذا السجل موجود مسبقًا'],['row-level security','الصلاحيات لا تسمح بهذه العملية']];for(var i=0;i<map.length;i++)if(code.indexOf(map[i][0])>=0)return map[i][1];return (e&&e.message)||'تعذرت العملية'};
