O.safe=async function(p,label){try{var r=await p;if(r&&r.error)throw r.error;return r&&r.data||[]}catch(e){console.warn('ACOPS '+(label||''),e);return []}};
O.rpc=async function(name,args,retry){var r=await sb.rpc(name,args||{});if(r.error&&r.error.code==='PGRST303'&&!retry){try{await sb.auth.refreshSession()}catch(e){}return O.rpc(name,args,true)}if(r.error)throw r.error;return r.data};
O.orgId=async function(){if(O._orgId)return O._orgId;var ids=await O.rpc('pi_my_orgs',{});O._orgId=Array.isArray(ids)?ids[0]:ids; if(!O._orgId)throw new Error('لا توجد جهة مرتبطة بهذا الحساب');return O._orgId};
O.guard=function(){return typeof ME!=='undefined'&&ME&&ME.role==='academy'};
O.invalidate=function(){O.cache=null;O.cacheAt=0};
O.load=async function(force){
  if(!O.guard())throw new Error('هذه المساحة مخصصة للأكاديمية');
  if(!force&&O.cache&&Date.now()-O.cacheAt<20000)return O.cache;
  var oid=await O.orgId(),org=(ME&&ME.org)||'';
  var settled=await Promise.allSettled([
    O.rpc('my_organization_erp_workspace',{p_organization_id:oid}),
    O.rpc('my_organization_workspace',{p_organization_id:oid}),
    O.rpc('my_store_workspace',{p_organization_id:oid}),
    O.rpc('my_conversation_center',{}),
    O.safe(sb.from('profiles').select('id,name,display_name,handle,role,org,pos,age,shirt,avatar_url,guardian_name,guardian_consent_at').eq('org',org).limit(600),'profiles'),
    O.safe(sb.from('pi_seats').select('*').eq('org',org).order('created_at',{ascending:false}).limit(600),'seats'),
    O.safe(sb.from('subscriptions').select('*').eq('org',org).order('month',{ascending:false}).limit(1000),'legacy subscriptions'),
    O.safe(sb.from('attendance').select('*').eq('org',org).order('created_at',{ascending:false}).limit(3000),'attendance'),
    O.safe(sb.from('bookings').select('*').order('created_at',{ascending:false}).limit(500),'bookings'),
    O.safe(sb.from('payments').select('*').eq('payee_organization_id',oid).order('created_at',{ascending:false}).limit(1000),'payments'),
    O.safe(sb.from('training_sessions').select('*').eq('organization_id',oid).order('starts_at',{ascending:false}).limit(500),'training'),
    O.rpc('my_organization_expense_center',{p_organization_id:oid}),
    O.rpc('my_organization_campaign_center',{p_organization_id:oid}),
    O.rpc('my_organization_lead_center',{p_organization_id:oid}),
    O.rpc('my_organization_feature_center',{p_organization_id:oid}),
    O.rpc('my_organization_form_center',{p_organization_id:oid}),
    O.rpc('my_organization_outbound_center',{p_organization_id:oid}),
    O.rpc('my_organization_loyalty_center',{p_organization_id:oid}),
    O.rpc('my_organization_settings_center',{p_organization_id:oid}),
    O.rpc('my_organization_integration_event_center',{p_organization_id:oid,p_limit:200}),
    O.safe(sb.from('notifications').select('*').eq('user_id',ME.id).order('created_at',{ascending:false}).limit(200),'notifications')
  ]);
  function v(i,d){return settled[i].status==='fulfilled'?settled[i].value:d}
  O.cache={oid:oid,org:org,erp:v(0,{}),workspace:v(1,{}),store:v(2,{}),conversations:v(3,{}),profiles:v(4,[]),seats:v(5,[]),legacySubs:v(6,[]),attendance:v(7,[]),bookings:v(8,[]),payments:v(9,[]),training:v(10,[]),expenses:(v(11,{}).expenses||[]),marketing:(v(12,{}).campaigns||[]),leads:(v(13,{}).leads||[]),features:(v(14,{}).items||[]),forms:v(15,{}),outbound:(v(16,{}).messages||[]),loyalty:v(17,{}),settingsSections:(v(18,{}).sections||{}),integrationEvents:v(19,{}),notifications:v(20,[])};
  O.cacheAt=Date.now();return O.cache;
};
O.withAction=async function(btn,fn,ok){var b=btn&&btn.nodeType?btn:null,old=b?b.innerHTML:'';if(b){b.disabled=true;b.innerHTML='جارٍ التنفيذ…'}try{await fn();O.invalidate();O.toast(ok||'تم الحفظ');if(typeof render==='function')await render()}catch(e){console.error(e);O.toast(O.errorText(e),1)}finally{if(b){b.disabled=false;b.innerHTML=old}}};
