O.addCustomer=function(btn){return O.withAction(btn,async function(){var d=await O.load(),name=O.val('opsCustomerName'),group=O.val('opsCustomerGroup'),age=Number(O.val('opsCustomerAge')||0),phone=O.val('opsCustomerPhone');if(!name)throw new Error('اسم اللاعب مطلوب');var code='PI-'+Math.random().toString(36).slice(2,8).toUpperCase();var r=await sb.from('pi_seats').insert({org:d.org,name:name,group_name:group,pos:O.val('opsCustomerPos'),age:age||null,phone:phone,join_code:code,created_by:ME.name}).select().single();if(r.error)throw r.error},'تم تسجيل العميل وإصدار رمز الانضمام')};
O.createPlan=function(btn){return O.withAction(btn,async function(){var d=await O.load(),name=O.val('opsPlanName'),amount=Number(O.val('opsPlanAmount')),type=O.val('opsPlanType')||'subscription',freq=O.val('opsPlanFrequency')||'monthly',tax=Number(O.val('opsPlanTax')||0);if(!name||amount<0)throw new Error('أدخل اسم الباقة وقيمتها');await O.rpc('create_my_organization_fee_plan',{p_organization_id:d.oid,p_name:name,p_fee_type:type,p_billing_frequency:freq,p_amount:amount,p_tax_rate:tax,p_currency:'SAR',p_starts_at:new Date().toISOString().slice(0,10),p_ends_at:null})},'تم إنشاء الباقة')};
O.createSubscription=function(btn){return O.withAction(btn,async function(){var d=await O.load(),plan=O.val('opsSubPlan'),member=O.val('opsSubMember');if(!plan||!member)throw new Error('اختر الباقة والعضو');await O.rpc('create_my_organization_subscription',{p_organization_id:d.oid,p_fee_plan_id:plan,p_membership_id:member,p_starts_at:new Date().toISOString().slice(0,10),p_ends_at:null,p_next_billing_at:new Date().toISOString().slice(0,10)})},'تم إنشاء الاشتراك')};
O.issueInvoice=function(id,btn){return O.withAction(btn,async function(){var d=await O.load(),now=new Date(),key=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');await O.rpc('issue_my_subscription_invoice',{p_organization_id:d.oid,p_subscription_id:id,p_billing_period_key:key,p_due_at:new Date(Date.now()+7*86400000).toISOString()})},'تم إصدار الفاتورة')};
