O.subscriptionAction=function(id,action,btn){return O.withAction(btn,async function(){var d=await O.load();await O.rpc('act_my_organization_subscription',{p_organization_id:d.oid,p_subscription_id:id,p_action:action})},action==='cancel'?'تم إلغاء الاشتراك':action==='pause'?'تم إيقاف الاشتراك مؤقتًا':'تم تفعيل الاشتراك')};
O.voidInvoice=function(id,btn){return O.withAction(btn,async function(){var d=await O.load();await O.rpc('void_my_organization_invoice',{p_organization_id:d.oid,p_invoice_id:id,p_reason:'Voided by academy operations user'})},'تم إلغاء الفاتورة غير المدفوعة')};
O.recordPayment=function(btn){return O.withAction(btn,async function(){var d=await O.load(),invoice=O.val('opsPayInvoice'),amount=Number(O.val('opsPayAmount')),provider=O.val('opsPayProvider')||'manual',ref=O.val('opsPayRef');if(!invoice||amount<=0)throw new Error('اختر الفاتورة وأدخل المبلغ');await O.rpc('record_my_erp_external_payment',{p_organization_id:d.oid,p_invoice_id:invoice,p_amount:amount,p_provider:provider,p_provider_reference:ref||null})},'تم تسجيل التحصيل وإصدار الأثر المالي')};
